{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a quarter's demand (contract reservation) exceeds what is produced and available from inventory, is the shortfall allowed to be carried over as backorder into the next quarter (incurring the delay compensation for each quarter it is late), or must every quarter's demand be fully met by the end of that same quarter?"
  ],
  "rationale": "The response asks for a single policy choice regarding how to handle unmet demand (backlog vs. immediate fulfillment), which constitutes one semantically independent question."
}

{
  "action": "question",
